def length(head):
    count = 0
    current = head
    while current is not None:
        count += 1
        current = current.next
    return count

def contains(head, target):
    current = head
    while current is not None:
        if current.val == target:
            return True
        current = current.next
    return False

print(length(a), contains(a, 'b'), contains(a, 'z'))  # 3 True False
Same walk, different work at each node; return True as soon as a match is found, False only after the whole chain.

