def remove_value(items, target):
    prev = None
    current = items.head
    while current is not None:
        if current.val == target:
            if prev is None:
                items.head = current.next
            else:
                prev.next = current.next
            return True
        prev = current
        current = current.next
    return False

print(remove_value(items, 'b'), items.to_list())  # True ['a', 'c']
Keep a prev pointer one step behind; prev.next = current.next skips the removed node. Removing the head (prev is None) is a separate case.

