def is_balanced(node):
    if node is None:
        return True
    if abs(height(node.left) - height(node.right)) > 1:
        return False
    return is_balanced(node.left) and is_balanced(node.right)

root = None
for v in [2, 1, 3, 4, 5]:
    root = insert(root, v)
print(is_balanced(root))  # False
A tree is height-balanced when, at every node, the two subtree heights differ by at most 1. The root alone looking fine is not enough.

