def collect(node, prefix, words):
    for key, child in node.items():
        if key == '*':
            words.append(prefix)
        else:
            collect(child, prefix + key, words)
    return words

trie = {}
for w in ['car', 'cat', 'do']:
    insert(trie, w)
print(sorted(collect(trie, '', [])))  # ['car', 'cat', 'do']
Pass down the letters so far; whenever '*' appears, the prefix is a complete word.

# insert and collect as above
def complete(trie, prefix):
    node = trie
    for ch in prefix:
        if ch not in node:
            return []
        node = node[ch]
    return sorted(collect(node, prefix, []))

trie = {}
for w in ['car', 'cart', 'cat', 'dog']:
    insert(trie, w)
print(complete(trie, 'car'))  # ['car', 'cart']
