# insert(trie, word) as defined earlier
def find_words(trie, text):
    found = set()
    for start in range(len(text)):
        node = trie
        for end in range(start, len(text)):
            if text[end] not in node:
                break
            node = node[text[end]]
            if '*' in node:
                found.add(text[start:end + 1])
    return found

trie = {}
for w in ['cat', 'at', 'dog']:
    insert(trie, w)
print(sorted(find_words(trie, 'concatenate')))  # ['at', 'cat']
From every starting position walk the trie as far as the text allows; each '*' passed is a match. One walk checks every word at once.

def add_edge(graph, u, v):
