graph = {'A': {'B', 'C'}, 'B': {'A', 'D'}, 'C': {'A', 'D'}, 'D': {'B', 'C', 'E'}, 'E': {'D'}}

def dfs_stack(graph, start):
    visited = set()
    order = []
    stack = [start]
    while stack:
        v = stack.pop()
        if v in visited:
            continue
        visited.add(v)
        order.append(v)
        for n in sorted(graph[v], reverse=True):
            stack.append(n)
    return order

print(dfs_stack(graph, 'A'))  # ['A', 'B', 'D', 'C', 'E']
The stack replaces the call stack; pushing neighbours in reverse makes the smallest pop first, matching the recursive order.

