def reachable(graph, start, goal, visited):
    if start == goal:
        return True
    visited.add(start)
    for n in graph[start]:
        if n not in visited and reachable(graph, n, goal, visited):
            return True
    return False

print(reachable(graph, 'A', 'E', set()), reachable(graph, 'A', 'G', set()))  # True False
Stop as soon as the goal is found; a False answer means DFS ran out of places to go.

from collections import deque
graph = {'A': {'B', 'C'}, 'B': {'A', 'D'}, 'C': {'A', 'D'}, 'D': {'B', 'C', 'E'}, 'E': {'D'}}

def bfs(graph, start):
    visited = {start}
    order = []
    queue = deque([start])
    while queue:
        v = queue.popleft()
        order.append(v)
        for n in sorted(graph[v]):
            if n not in visited:
                visited.add(n)
                queue.append(n)
    return order

print(bfs(graph, 'A'))  # ['A', 'B', 'C', 'D', 'E']
All neighbours of A come before any of their neighbours: first in, first out gives level-by-level order.

