def distances(graph, start):
    dist = {start: 0}
    queue = deque([start])
    while queue:
        v = queue.popleft()
        for n in graph[v]:
            if n not in dist:
                dist[n] = dist[v] + 1
                queue.append(n)
    return dist

print(distances(graph, 'A')['E'])  # 3
The dist dict doubles as the visited set; a vertex's distance is one more than the vertex that found it.

# deque and graph as in breadth_first_search KP1
def parents(graph, start):
    parent = {start: None}
    queue = deque([start])
    while queue:
        v = queue.popleft()
        for n in sorted(graph[v]):
            if n not in parent:
                parent[n] = v
                queue.append(n)
    return parent

print(parents(graph, 'A'))  # {'A': None, 'B': 'A', 'C': 'A', 'D': 'B', 'E': 'D'}
parent[n] = v records the edge BFS used to reach n first, which is on a shortest route.

