If BFS never reached the goal it has no parent entry; return None rather than crashing with KeyError.

from collections import deque
maze = ['..#', '#..', '...']

def neighbours(r, c):
    result = []
    for dr, dc in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < len(maze) and 0 <= nc < len(maze[0]) and maze[nr][nc] == '.':
            result.append((nr, nc))
    return result

dist = {(0, 0): 0}
queue = deque([(0, 0)])
while queue:
    r, c = queue.popleft()
    for n in neighbours(r, c):
        if n not in dist:
            dist[n] = dist[(r, c)] + 1
            queue.append(n)
print(dist[(2, 2)])  # 4
Open cells are vertices and steps to adjacent open cells are edges, computed on the fly instead of stored.

