grid = ['##..',
        '#..#',
        '...#']
seen = set()

def sink(r, c):
    if not (0 <= r < len(grid) and 0 <= c < len(grid[0])):
        return
    if grid[r][c] != '#' or (r, c) in seen:
        return
    seen.add((r, c))
    for dr, dc in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
        sink(r + dr, c + dc)

islands = 0
for r in range(len(grid)):
    for c in range(len(grid[0])):
        if grid[r][c] == '#' and (r, c) not in seen:
            islands += 1
            sink(r, c)
print(islands)  # 2
Land cells are vertices joined to land above, below, left and right; the same outer-loop pattern counts the pieces.

links = {'A': ['B', 'C'], 'B': ['C'], 'C': ['A']}
rank = {p: 1 / 3 for p in links}
new = {p: 0 for p in links}
for page, outs in links.items():
    for target in outs:
        new[target] += rank[page] / len(outs)
print({p: round(r, 3) for p, r in new.items()})  # {'A': 0.333, 'B': 0.167, 'C': 0.5}
A splits its 1/3 between B and C; B gives all of its 1/3 to C; C gives its 1/3 to A. Ranks still add up to 1.

links = {'A': ['B', 'C'], 'B': ['C'], 'C': ['A']}
rank = {p: 1 / 3 for p in links}
for _ in range(50):
    new = {p: 0 for p in links}
    for page, outs in links.items():
        for target in outs:
            new[target] += rank[page] / len(outs)
    rank = new
print({p: round(r, 2) for p, r in rank.items()})  # {'A': 0.4, 'B': 0.2, 'C': 0.4}
Each round moves rank along the links; after enough rounds the numbers stop changing. Pages that many ranked pages link to end up highest.

links = {'A': ['B'], 'B': ['A'], 'C': ['A']}
d = 0.85
n = len(links)
rank = {p: 1 / n for p in links}
for _ in range(50):
    new = {p: (1 - d) / n for p in links}
    for page, outs in links.items():
        for target in outs:
            new[target] += d * rank[page] / len(outs)
    rank = new
print({p: round(r, 2) for p, r in rank.items()})  # {'A': 0.49, 'B': 0.46, 'C': 0.05}
Each page keeps a small base share (1 - d) / n, as if a surfer sometimes jumps to a random page, so ranks do not drain into closed loops; C gets only the base share because nothing links to it.

